def compare(a, b):
    le = all(x <= y for x, y in zip(a, b))
    ge = all(x >= y for x, y in zip(a, b))
    if le and not ge:
        return "a -> b"
    if ge and not le:
        return "b -> a"
    return "equal" if le else "concurrent"

print(compare((2, 0, 1), (1, 1, 1)))

def more_up_to_date(a, b):          # (last_term, last_index)
    if a[0] != b[0]:
        return a[0] > b[0]
    return a[1] >= b[1]

